(function(){'use strict';if(!document.body.hasAttribute('data-account-required'))return;let blocked=false;async function check(){try{const r=await fetch('/api/account/session',{credentials:'same-origin',signal:AbortSignal.timeout(10000)}),s=await r.json();if(!r.ok||!s.signedIn||!s.access.some(a=>a.guided))throw Error();if(blocked){document.getElementById('account-session-hold')?.remove();document.querySelector('.g-shell').inert=false;blocked=false}}catch{if(blocked)return;blocked=true;const main=document.querySelector('.g-shell');main.inert=true;const panel=document.createElement('section');panel.id='account-session-hold';panel.setAttribute('role','alertdialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-labelledby','account-hold-title');panel.style.cssText='position:fixed;inset:15% 8%;overflow:auto;background:white;border:3px solid #11243d;padding:28px;z-index:99999;box-shadow:0 0 0 100vmax #11243dcc';panel.innerHTML='<h2 id="account-hold-title" tabindex="-1">Plan access needs verification</h2><p>Your browser selections have not been uploaded. Access may have expired, been revoked or become temporarily unverifiable. A new page or reload clears this session.</p><button id="account-save-session" class="btn btn-light">Save a full recovery file</button><button id="account-recheck" class="btn btn-light">Check access again</button><a class="btn btn-dark" href="/account" target="_blank" rel="noopener">Open account in a new tab</a><p>Keep this tab open while you sign in again. Return here and choose Check access again. If your plan has ended, contact your plan provider.</p>';document.body.append(panel);document.getElementById('account-save-session').onclick=()=>{if(window.NavigatorSessionExperience)window.NavigatorSessionExperience.save();else document.getElementById('timeline-export')?.click();};document.getElementById('account-recheck').onclick=check;document.getElementById('account-hold-title').focus()}}check();setInterval(check,300000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)check()})})();
